namespace MotoGrid.Services.Storage;

/// <summary>
/// Saves the files on the local disk of the web server.
/// File names are generated by the server (GUID), so a user cannot overwrite
/// other files or use "../" to write outside of the uploads folder.
/// </summary>
public class LocalFileStorage : IFileStorage
{
    private readonly FileStorageOptions options;

    public LocalFileStorage(FileStorageOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);
        ArgumentException.ThrowIfNullOrWhiteSpace(options.RootPath);

        this.options = options;
    }

    public async Task<string> SaveAsync(Stream content, string fileName, string folder, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(content);
        ArgumentException.ThrowIfNullOrWhiteSpace(fileName);

        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        if (!this.options.AllowedExtensions.Contains(extension))
        {
            throw new InvalidOperationException($"Files of type '{extension}' are not allowed.");
        }

        if (content.CanSeek && content.Length > this.options.MaxFileSizeBytes)
        {
            throw new InvalidOperationException("The file is too large.");
        }

        var safeFolder = SanitizeFolder(folder);
        var directory = Path.Combine(this.options.RootPath, safeFolder);
        Directory.CreateDirectory(directory);

        var storedName = $"{Guid.NewGuid():N}{extension}";
        var fullPath = Path.Combine(directory, storedName);

        await using (var file = new FileStream(fullPath, FileMode.CreateNew, FileAccess.Write))
        {
            await content.CopyToAsync(file, cancellationToken);
        }

        if (new FileInfo(fullPath).Length > this.options.MaxFileSizeBytes)
        {
            File.Delete(fullPath);
            throw new InvalidOperationException("The file is too large.");
        }

        var urlFolder = string.IsNullOrEmpty(safeFolder) ? string.Empty : safeFolder + "/";
        return $"{this.options.RequestPath.TrimEnd('/')}/{urlFolder}{storedName}";
    }

    public Task<bool> DeleteAsync(string url, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(url) ||
            !url.StartsWith(this.options.RequestPath, StringComparison.OrdinalIgnoreCase))
        {
            return Task.FromResult(false);
        }

        var relative = url[this.options.RequestPath.Length..].TrimStart('/');
        var root = Path.GetFullPath(this.options.RootPath);
        var fullPath = Path.GetFullPath(Path.Combine(root, relative));

        // Never delete anything outside of the uploads folder
        if (!fullPath.StartsWith(root, StringComparison.OrdinalIgnoreCase) || !File.Exists(fullPath))
        {
            return Task.FromResult(false);
        }

        File.Delete(fullPath);
        return Task.FromResult(true);
    }

    /// <summary>
    /// Keeps only letters, digits, '-' and '_' in each part of the folder name.
    /// </summary>
    private static string SanitizeFolder(string? folder)
    {
        if (string.IsNullOrWhiteSpace(folder))
        {
            return string.Empty;
        }

        var parts = folder
            .Split(['/', '\\'], StringSplitOptions.RemoveEmptyEntries)
            .Select(p => new string(p.Where(c => char.IsLetterOrDigit(c) || c == '-' || c == '_').ToArray()))
            .Where(p => p.Length > 0);

        return string.Join('/', parts);
    }
}
